%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Non-parametric Statistical Testing through Permutation
%$$$$$$
%$$$$$$ This script is for analysis of time-voltage data that have been
%$$$$$$ cleaned and pre-processed through the standard SMILe routine
%$$$$$$ 
%$$$$$$ Based on the Monte Carlo Simulation framework
%$$$$$$ 
%$$$$$$ JCM, current as of 12/07/2018
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ DO NOT EDIT THIS FILE
%$$$$$$ MAKE A COPY OF THIS FILE AND SAVE IT TO YOUR HARD DRIVE
%$$$$$$ THEN, AND ONLY THEN, MAKE IT WORK FOR YOUR UNIQUE SETTINGS
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Gather data to be used for the permutation test. As of now, this
%$$$$$$ will accept two conditions.
%$$$$$$
%$$$$$$ allsubj and allsubjavg are data sets that should have been
%$$$$$$ proprocessed through the standard SMILe EEGLAB processing script,
%$$$$$$ and then run through the FieldTrip conversion script 
%$$$$$$ (FT_Convert_EEGLAB) and finally through FT_TimeLock
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%%
load 'path/to/data/allsubj.mat';
load 'path/to/data/allsubjavg.mat';

%--------------------------------------------------------------------------
% To make things as simple as possible, declare dummy variables for the two
% conditions (var1 and var2). Only modify the input that creates var1 and
% var2.
%
% As currently written, var1 and var2 should be structures with subjects in 
% the second dimension and the main field 'sub'. 
% Other simensions should be as follows:
%   var1(1).sub[channels time trials]
%--------------------------------------------------------------------------
var1 = [];
tmp = [];

for i = 1:size(allsubj,2)
    for ii = 1:size(allsubj(i).cor.trial,2)
    tmp(:,:,ii) = allsubj(i).cor.trial{ii};
  
    end
    
    var1(i).sub = tmp;
    clear tmp
    
end

var2 = [];
tmp=[];
for i = 1:size(allsubj,2)
    for ii = 1:size(allsubj(i).con.trial,2)
    tmp(:,:,ii) = allsubj(i).con.trial{ii};
  
    end
    
    var2(i).sub = tmp;
    clear tmp
    
end

%--------------------------------------------------------------------------
% This is an alternative way to load the data and concatenate at the same
% time while skipping an additional step. This results in var1 and var2 
% having the dimensions of [channels x time x trials]
%--------------------------------------------------------------------------
% var1 = [];
% 
% for i = 1:size(allsubj,2)
%     for ii = 1:size(allsubj(i).cor.trial,2)
%     var1 = cat(3,var1,allsubj(i).cor.trial{ii});
%     end
% end

% var2 = [];
% 
% for i = 1:size(allsubj,2)
%     for ii = 1:size(allsubj(i).con.trial,2)
%     var2 = cat(3,var1,allsubj(i).con.trial{ii});
%     end
% end

%%
dataFolder = 'path/to/data';

%--------------------------------------------------------------------------
% Identify the subject numbers for processing.
%
% Maybe someday try modifying fnames = findfiles('Y_*.set', dataFolder);
%--------------------------------------------------------------------------
subjs= {...
    'Y_S001-EEG'...
    'Y_S002-EEG'...
    'Y_S004-EEG'...
    'Y_S005-EEG'...
    'Y_S006-EEG'...
    'Y_S007-EEG'...
    'Y_S008-EEG'...
    'Y_S009-EEG'...
    'Y_S010-EEG'...
    'Y_S011-EEG'...
    'Y_S012-EEG'...
    'Y_S011-EEG'...
    'Y_S012-EEG'...
    'Y_S014-EEG'...
    'Y_S015-EEG'...
    'Y_S016-EEG'...
    'Y_S017-EEG'...
    'Y_S019-EEG'...
    'Y_S020-EEG'...
    'Y_S022-EEG'...
    'Y_S024-EEG'...
    'Y_S025-EEG'...
    };
conds = {'2' '4' '8' '16' '32' '64'};

%--------------------------------------------------------------------------
% Load each individual condition file, and concatenate into one large EEG
% structure.
%--------------------------------------------------------------------------
for nCond = 1:size(conds,2)
    for nSub = 1:size(subjs,2)
        nSub
        nCond
 
        if nSub == 1
            EEG = pop_loadset('filename',strcat(subjs(nSub),'_',conds(nCond),'.set'),'filepath',dataFolder);

        elseif nSub > 1
            EEGtmp = pop_loadset('filename',strcat(subjs(nSub),'_',conds(nCond),'.set'),'filepath',dataFolder);
            EEG = pop_mergeset(EEG,EEGtmp);
            pause(2)
            clear EEGtmp

        end
        
        if nCond == 1
            cor = EEG;
        
        elseif nCond == 2
            plaus = EEG;
            
        elseif nCond == 3
            con = EEG;
            
        elseif nCond == 4
            manip = EEG;
            
        end
    end
    
end

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Start concatenation of the two conditions indivisually
%$$$$$$
%$$$$$$ The resulting var1_3d and var2_3d should have the dimensions of
%$$$$$$ [channels x time x trials]
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
var1_3d = cor.data;
var2_3d = plaus.data;
% var1_3d = [];
% var2_3d = [];
% for i = 1:size(var1,2)
% var1_3d = cat(3,var1_3d, squeeze(var1(i).sub(:,:,:)));
% var2_3d = cat(3,var2_3d, squeeze(var2(i).sub(:,:,:)));
% 
% end

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Plot one channel of the raw data
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
figure; 
hold on
plot(smooth(smooth(mean(var1_3d(4,:,:),3))))
plot(smooth(smooth(mean(var2_3d(4,:,:),3))),'r')


%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Compute the difference between the two conditions. For
%$$$$$$ consistency, differences will always be var2 - var1
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
diffwave = squeeze(mean(var2_3d,3)) - squeeze(mean(var1_3d,3));

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Start concatenation of the two conditions into a single variable
%$$$$$$
%$$$$$$ The resulting all3d represents all data from the two conditions,
%$$$$$$ effectively "stacked" on top of one another (var1_3d | var_2d) and 
%$$$$$$ should have the dimensions of [channels x time x trials], where
%$$$$$$ trials should be equal to size(var1_3d,3) + size(var2_3d,3).
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
all3d = cat(3,var1_3d, var2_3d);

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Determine the number of permutations to impliment. 1000 is a
%$$$$$$ standard number in the literature. 
%$$$$$$
%$$$$$$ Keep in mind that this procedure is (hugely) computationally
%$$$$$$ expensive as you assign permutation numbers.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
n_permutes = 1000;

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Pull the number of channels from the data.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
n_chans = size(all3d,1);

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Pull the number of timepoints from the data.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
n_times = size(all3d,2);

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Pull the number of trials from the data. This can't be 
%$$$$$$ size(all3d,3) because there might be an uneven number of trials
%$$$$$$ from condition 1 to condition 2.
%$$$$$$
%$$$$$$ So, pull the trials from one condition (var1_3d).
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
n_trials = size(var1_3d,3);

%%
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$
%$$
%$$$$$$ Now, begin the permutation to construct the null matrices (Ho).
%$$$$$$
%$$$$$$ This can tale some time.
%$$
%$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$$

%--------------------------------------------------------------------------
% Begin with initiaizing the null matrix:
%--------------------------------------------------------------------------
permwaves = zeros(n_permutes,n_chans,n_times);

%--------------------------------------------------------------------------
% Start a timer:
%--------------------------------------------------------------------------
tstart = tic;
fprintf('##################################################################################################################\n\n');
fprintf('Beginning Permutations ----- '); disp(datestr(now))
fprintf('\n')
fprintf('##################################################################################################################\n\n');

%--------------------------------------------------------------------------
% Generate waveforms under the null hypothesis:
%--------------------------------------------------------------------------
for permi = 1:n_permutes
    
%--------------------------------------------------------------------------
% Randomize trials, which also randomly assigns trials to channels:
%--------------------------------------------------------------------------    
    randorder = randperm(size(all3d,3));
    tmp3d = all3d(:,:,randorder);
    
%--------------------------------------------------------------------------
% Compute the "difference" waveform:
%--------------------------------------------------------------------------    
    permwaves(permi,:,:) = squeeze(mean(tmp3d(:,:,1:n_trials),3) - mean(tmp3d(:,:,n_trials+1:end),3));
    
end

%--------------------------------------------------------------------------
% End timer and display result:
%--------------------------------------------------------------------------
telapsed = toc(tstart);
telapsed = telapsed / 60;
fprintf('##################################################################################################################\n\n');
fprintf('All files processed ... time elapsed is %s minutes.\n\n', telapsed);
disp(datestr(now) )
fprintf('##################################################################################################################\n\n');

%%
% p-value
pval = 0.05;

% convert p-value to Z value
zval = abs(norminv(pval));
% show non-corrected thresholded maps

% compute mean and standard deviation maps
mean_h0 = squeeze(mean(permwaves));
std_h0  = squeeze(std(permwaves));

% now threshold real data...
% first Z-score
zdiff = (diffwave-mean_h0) ./ std_h0;

% threshold image at p-value, by setting subthreshold values to 0
zdiff(abs(zdiff)<zval) = 0;
plot(zdiff(5,:))
